/**
 * Remediation resolution generator for Cloud Run server.js
 *
 * Produces the "Resolution" beside each remediation item's action — the concrete,
 * document-specific fix, generated by TWO independent models (Gemini + Claude)
 * reading the client's actual document, then cross-checked: if the models cite the
 * same sections they AGREE (auto-draft); if they diverge it is FLAGGED for review.
 * Stored in remediation_resolutions (migration 022). Nik edits/approves.
 *
 * Endpoints:
 *  - POST /api/remediation/:id/generate-resolution
 *  - GET  /api/remediation/:id/resolution
 *  - PUT  /api/remediation/:id/resolution        (edit / approve: resolution, status)
 *
 * Requires GEMINI_API_KEY + ANTHROPIC_API_KEY env vars (Cloud Run secrets).
 * DPA-tier note: safe on STZA's own data; client personal data needs DPA-covered
 * AI tiers (Vertex Gemini + Anthropic commercial DPA) before use.
 */

const GEMINI_MODEL = process.env.GEMINI_MODEL || "gemini-pro-latest";
const CLAUDE_MODEL = process.env.CLAUDE_MODEL || "claude-opus-4-8";
const MAX_CHARS = 40000;

// Which document types are most relevant per finding category.
const CATEGORY_DOCS = {
  special_categories: ["privacy_policy", "impact_assessment"],
  breach_notification: ["breach_procedure", "privacy_policy"],
  security_safeguards: ["security_policy", "privacy_policy"],
  cross_border_transfer: ["data_processing_agreement", "privacy_policy"],
  information_officer: ["privacy_policy", "other"],
  data_subject_rights: ["privacy_policy"],
  consent_mechanism: ["privacy_policy", "consent_form"],
  retention_and_purpose: ["privacy_policy", "retention_policy"],
  lawful_processing: ["privacy_policy", "data_processing_agreement"],
  direct_marketing: ["privacy_policy", "marketing_policy"],
};

const RESOLUTION_SYSTEM = `You are a data-protection compliance assessor. You are given ONE remediation finding and the client's actual document(s). Produce a concrete, specific resolution.
Rules:
- Identify EXACTLY what is missing or wrong in the client's document text for this finding — quote the relevant wording where possible.
- Provide a concrete redraft: the corrected clause/paragraph the client could adopt (mark it as a draft, pending the client's own legal review).
- Cite the EXACT statutory section numbers that apply. Do not invent sections. Be precise (e.g. children's data is POPIA s34-35, not s26).
- Judge only from the document text; do not assume facts not stated.
- Respond with ONLY a JSON object:
  {"summary":"one sentence on the core gap","gaps":["specific gap 1","gap 2"],"redraft":"the suggested corrected clause text","citations":["s26","s27(1)(b)"]}`;

function stripHtml(h) {
  return (h || "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&[a-z]+;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractJson(t) {
  if (!t) return null;
  const m = t.match(/\{[\s\S]*\}/);
  try {
    return JSON.parse(m ? m[0] : t);
  } catch {
    return null;
  }
}

async function callGemini(user) {
  const key = process.env.GEMINI_API_KEY;
  if (!key) throw new Error("GEMINI_API_KEY not configured");
  const r = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${key}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        system_instruction: { parts: [{ text: RESOLUTION_SYSTEM }] },
        contents: [{ role: "user", parts: [{ text: user }] }],
        generationConfig: {
          temperature: 0,
          thinkingConfig: { thinkingBudget: -1 },
          responseMimeType: "application/json",
        },
      }),
    },
  );
  if (!r.ok) throw new Error(`Gemini ${r.status}: ${(await r.text()).slice(0, 150)}`);
  const d = await r.json();
  return extractJson(d?.candidates?.[0]?.content?.parts?.[0]?.text);
}

async function callClaude(user, attempt = 0) {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error("ANTHROPIC_API_KEY not configured");
  const r = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "x-api-key": key,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: CLAUDE_MODEL,
      max_tokens: 3000,
      thinking: { type: "adaptive" },
      system: RESOLUTION_SYSTEM,
      messages: [{ role: "user", content: user }],
    }),
  });
  if (r.status === 529 && attempt < 2) {
    await new Promise((res) => setTimeout(res, 1500 * (attempt + 1)));
    return callClaude(user, attempt + 1); // retry on overload
  }
  if (!r.ok) throw new Error(`Claude ${r.status}: ${(await r.text()).slice(0, 150)}`);
  const d = await r.json();
  const text = (d.content || []).find((b) => b.type === "text")?.text;
  return extractJson(text);
}

// Normalise a citation for comparison (strip spaces/case, keep section digits+letters).
const normCite = (s) => (s || "").toLowerCase().replace(/[^a-z0-9()]/g, "");

function crossCheck(g, c) {
  const gc = new Set((g?.citations || []).map(normCite).filter(Boolean));
  const cc = new Set((c?.citations || []).map(normCite).filter(Boolean));
  if (!gc.size || !cc.size) return "flagged";
  // Agreed if the smaller set is fully contained in the larger (aligned citations).
  const [small, big] = gc.size <= cc.size ? [gc, cc] : [cc, gc];
  const contained = [...small].every((x) => big.has(x));
  return contained ? "agreed" : "flagged";
}

function composeResolution(primary, other, agreement) {
  const lines = [];
  if (agreement === "flagged") {
    lines.push(
      "REVIEW: the two models cited different sections — confirm which is correct before adopting.",
    );
  }
  if (primary?.summary) lines.push(primary.summary);
  if (primary?.gaps?.length) lines.push("Gaps:\n- " + primary.gaps.join("\n- "));
  if (primary?.redraft) lines.push("Suggested redraft (pending client legal review):\n" + primary.redraft);
  const cites = [...new Set([...(primary?.citations || []), ...(other?.citations || [])])];
  if (cites.length) lines.push("Citations: " + cites.join(", "));
  return lines.join("\n\n");
}

// ─── POST generate ──────────────────────────────────────────────────────────
app.post("/api/remediation/:id/generate-resolution", async (req, res) => {
  try {
    const { rows: items } = await pool.query(
      `SELECT * FROM remediation_items WHERE id = $1`,
      [req.params.id],
    );
    if (!items.length) return res.status(404).json({ error: "remediation item not found" });
    const item = items[0];

    const wantTypes = CATEGORY_DOCS[item.category] || ["privacy_policy"];
    const { rows: docs } = await pool.query(
      `SELECT document_type, title, COALESCE(raw_content, processed_content, '') AS content
       FROM compliance_documents WHERE client_id = $1`,
      [item.client_id],
    );
    let rel = docs.filter((d) => wantTypes.includes(d.document_type));
    if (!rel.length) rel = docs.filter((d) => d.document_type === "privacy_policy");
    if (!rel.length) rel = docs;
    const corpus = rel
      .map((d) => `## ${d.title} (${d.document_type})\n${stripHtml(d.content)}`)
      .join("\n\n")
      .slice(0, MAX_CHARS);

    const user = `FINDING: ${item.title} (${item.popia_reference || item.category})
Current finding: ${item.description || ""}
Standard recommendation: ${item.recommendation || ""}

CLIENT DOCUMENT(S):
"""
${corpus}
"""`;

    const [g, c] = await Promise.all([callGemini(user), callClaude(user)]);
    if (!g && !c) throw new Error("both models returned no parseable output");
    const agreement = g && c ? crossCheck(g, c) : "flagged";
    const primary = c || g; // prefer Claude as primary, fall back to Gemini
    const other = c ? g : null;
    const resolutionText = composeResolution(primary, other, agreement);
    const status = agreement === "flagged" ? "needs_review" : "draft";

    const { rows: saved } = await pool.query(
      `INSERT INTO remediation_resolutions
         (remediation_item_id, resolution, status, agreement, models, generated_at)
       VALUES ($1, $2, $3, $4, $5::jsonb, NOW())
       ON CONFLICT (remediation_item_id) DO UPDATE
         SET resolution = EXCLUDED.resolution,
             status     = EXCLUDED.status,
             agreement  = EXCLUDED.agreement,
             models     = EXCLUDED.models,
             generated_at = NOW(),
             updated_at = NOW()
       RETURNING *`,
      [
        item.id,
        resolutionText,
        status,
        agreement,
        JSON.stringify({ gemini: g, claude: c, models: [GEMINI_MODEL, CLAUDE_MODEL] }),
      ],
    );
    res.json(saved[0]);
  } catch (err) {
    console.error("POST /remediation/:id/generate-resolution error:", err);
    res.status(500).json({ error: err.message });
  }
});

// ─── GET resolution ───────────────────────────────────────────────────────────
app.get("/api/remediation/:id/resolution", async (req, res) => {
  try {
    const { rows } = await pool.query(
      `SELECT * FROM remediation_resolutions WHERE remediation_item_id = $1`,
      [req.params.id],
    );
    res.json(rows[0] || null);
  } catch (err) {
    console.error("GET /remediation/:id/resolution error:", err);
    res.status(500).json({ error: err.message });
  }
});

// ─── PUT resolution (edit / approve) ──────────────────────────────────────────
app.put("/api/remediation/:id/resolution", async (req, res) => {
  try {
    const { resolution, status, reviewed_by } = req.body;
    const { rows } = await pool.query(
      `UPDATE remediation_resolutions
       SET resolution = COALESCE($2, resolution),
           status     = COALESCE($3, status),
           reviewed_by = COALESCE($4, reviewed_by),
           reviewed_at = CASE WHEN $3 IN ('confirmed','applied') THEN NOW() ELSE reviewed_at END,
           updated_at = NOW()
       WHERE remediation_item_id = $1
       RETURNING *`,
      [req.params.id, resolution, status, reviewed_by],
    );
    if (!rows.length) return res.status(404).json({ error: "resolution not found" });
    res.json(rows[0]);
  } catch (err) {
    console.error("PUT /remediation/:id/resolution error:", err);
    res.status(500).json({ error: err.message });
  }
});
